/**
 * The first cycle a depth-first search finds, starting from each task in
 * ascending name order and walking each task's dependencies in ascending name
 * order. The cycle runs from the task the search re-entered, through the search
 * stack, back to that task, so its first and last name are the same.
 * @param {Map<string, {needs: string[]}>} tasks - the parsed tasks.
 * @returns {string[]|undefined} the cycle's names, or undefined when there is none.
 */
export function findCycle(tasks) {
  const done = new Set()
  const stack = []
  const onStack = new Set()

  function visit(name) {
    if (onStack.has(name)) return [...stack.slice(stack.indexOf(name)), name]
    if (done.has(name)) return undefined
    stack.push(name)
    onStack.add(name)
    for (const need of [...tasks.get(name).needs].sort()) {
      const cycle = visit(need)
      if (cycle !== undefined) return cycle
    }
    stack.pop()
    onStack.delete(name)
    done.add(name)
    return undefined
  }

  for (const name of [...tasks.keys()].sort()) {
    const cycle = visit(name)
    if (cycle !== undefined) return cycle
  }
  return undefined
}"}

