import { readFileSync } from 'node:fs'
import { splitLines } from './parse.js'

const DIGEST = /^[0-9a-f]{8}$/

/** One refusal of a snapshot, carrying the 1-based snapshot line, or 0 when it names none. */
export class SnapshotError extends Error {
  /**
   * @param {number} line - the 1-based snapshot line, or 0 when the failure names no line.
   * @param {string} message - the message the specification words, without any prefix.
   */
  constructor(line, message) {
    super(message)
    this.name = 'SnapshotError'
    this.line = line
  }
}

/**
 * Read a snapshot file into the digest it records for each path.
 * @param {string} path - the snapshot file.
 * @returns {Map<string, string>} the digest by path.
 */
export function readSnapshot(path) {
  let text
  try {
    text = readFileSync(path, 'utf8')
  } catch {
    throw new SnapshotError(0, `cannot read snapshot ${path}`)
  }
  const digests = new Map()
  for (const [index, raw] of splitLines(text).entries()) {
    const line = index + 1
    const entry = raw.trim()
    if (entry === '' || entry.startsWith('#')) continue
    const words = entry.split(/\s+/u)
    if (words.length !== 2) throw new SnapshotError(line, 'expected <path> <digest>')
    const [file, digest] = words
    if (!DIGEST.test(digest)) throw new SnapshotError(line, `invalid digest ${digest}`)
    if (digests.has(file)) throw new SnapshotError(line, `path ${file} is recorded twice`)
    digests.set(file, digest)
  }
  return digests
}
"}

